			&DeclareCommandFilter;



				&QueryString;

declare @queryWhereClause nvarchar(4000), @queryFormClause nvarchar(4000)
select @queryFormClause = 'left join dmkh b with(nolock, index(pk_dmkh)) on a.ma_kh = b.ma_kh left join dmct c with(nolock) on a.ma_ct = c.ma_ct left join dmvv d with(nolock) on a.ma_vv = d.ma_vv'
select @queryWhereClause = 'a.ma_phi = ''' + replace(@ma, '''', '''''') + ''''
If @nh_vv1 <> '' Set @queryWhereClause  = @queryWhereClause + 'AND d.nh_vv1 = ''' + replace(@nh_vv1, '''', '''''') + ''''


if @tk <> '' select @queryWhereClause = @queryWhereClause + ' and ' + dbo.FastBusiness$Function$System$GetAccountFilter('a.tk', 'inlist', @tk)

select @queryWhereClause = @queryWhereClause +
	case
		when @loai = 1 then ' and (ps_no + ps_no_nt <> 0)'
		when @loai = 2 then ' and (ps_co + ps_co_nt <> 0)' 
	end

&FilterInitialize;&FilterQuery;
exec FastBusiness$Report$GLDetail @@refresh, @@pageIndex, @@pageCount, @@lastPage, @@lastCount, @@firstItem, @@lastItem,
	@@textExternal, @queryFormClause, @queryWhereClause, @tu_ngay, @den_ngay, @ma_dvcs, @@admin, @@userID, @@aggregation







			&JavascriptReportInit;
			/* <flatten type="Javascript"> */
function init$GridQuery$(g) {
	var a = g._queryFilterString.split(String.fromCharCode(253));
	g._alterTitle = [null, [['%c', a[0], true], ['%s', g._Name, true]]];
	var x = a[6];
	g._hiddenFields = [{Fields: 'ps_no_nt, ps_co_nt', Value: (x == '10')}];
}
